const j = $input.first().json;
const raw = j.domains || j['domains'] || '';
const domains = String(raw).split('\n')
  .map(d => d.trim().replace(/^https?:\/\//,'').replace(/\/+$/,''))
  .filter(Boolean).slice(0, 10);
if (!domains.length) throw new Error('No domains provided');
return domains.map(d => ({ json: { domain: d } }));

const prevAll = $('Build Plan Payload').all();
const out = [];
$input.all().forEach((item, i) => {
  const prev = prevAll[i].json;
  const txt = (item.json.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim();
  const s = txt.indexOf('{'), e = txt.lastIndexOf('}');
  if (s === -1) throw new Error('Plan agent returned no JSON for ' + prev.domain);
  const plan = JSON.parse(txt.slice(s, e + 1));
  const isGeo = (plan.type || '').toLowerCase() === 'geo';
  const queries = (plan.discoverQueries && plan.discoverQueries.length ? plan.discoverQueries : [plan.discoverQuery]).slice(0, 3);
  queries.forEach(q => {
    const clean = String(q).replace(/site:\S+/gi, m => m.replace(/^site:/i,'').replace(/\.\w+$/,'')).replace(/["']/g, '').trim();
    out.push({ json: {
      domain: prev.domain, plan,
      searchUrl: isGeo ? 'https://google.serper.dev/places' : 'https://google.serper.dev/search',
      serperBody: { q: clean, num: 20, gl: 'us' }
    }});
  });
});
return out;

const DISCOVER_SYS = "You are an elite premium domain acquisition lead discovery agent. You receive a domain name, its classification, and merged Google search results. Your job is to identify REAL companies that have the highest probability of acquiring the domain.\n\nYour primary objective is QUALITY over quantity. Never invent companies or merge information from different companies with similar names.\n\nENTITY VERIFICATION:\nBefore returning a company, verify that its name, website, industry, funding, description, and search results all refer to the SAME organization. If multiple companies share the same name and the identity cannot be confidently verified, exclude the company.\n\nGEO DOMAINS:\nProspects are real businesses operating in the target city and niche.\nInclude small, medium, and established private businesses.\nNational directories, review sites, marketplaces, government websites, franchises, and listing websites (Yelp, Clutch, Expertise, FindLaw, Avvo, Justia, etc.) are NEVER prospects.\nHowever, businesses listed inside those directories ARE prospects.\nIf the website cannot be verified, leave it empty.\n\nBRANDABLE DOMAINS:\nProspects may include startups, private companies, scale-ups, venture-backed companies, and established businesses IF they have a credible reason to acquire the domain.\nDo NOT restrict prospects only to early-stage startups.\n\nPrioritize companies that:\n- Have an excellent keyword or brand match.\n- Operate directly within the domain's niche.\n- Could use the domain for a product, service, marketing campaign, expansion, rebrand, or defensive acquisition.\n- Use weaker domains (.io, .ai, .xyz, .co, .app, country-code TLDs, long domains, hyphenated domains, or multiple-word domains).\n- Recently launched products, entered new markets, raised funding, or announced strategic growth.\n\nCompanies already operating on a strong matching .com should generally receive a lower score unless the domain has clear product-branding or defensive acquisition value.\n\nExclude:\n- Public directories\n- Review sites\n- Government organizations\n- Universities\n- Accelerators\n- Incubators\n- VC firms\n- News websites\n- Blog articles\n- Conferences\n- Trade associations\n- Companies whose products are unrelated to the domain's commercial purpose\n\nReturn EVERY genuine buyer found in the search results.\nDo NOT pad results.\nDo NOT invent prospects.\nIf no genuine prospects exist, return an empty prospects array.\n\nScore every company using:\nBrand Fit (0-100)\nKeyword Match (0-100)\nCommercial Fit (0-100)\nLikelihood to Buy (0-100)\nOverall Score (0-100)\n\nPriority:\nHot\nWarm\nCold\n\nReturn ONLY valid raw JSON:\n{\"prospects\":[{\"name\":\"Company name\",\"website\":\"company domain or empty\",\"industry\":\"industry or Unknown\",\"why\":\"One concise sentence explaining why they are a realistic buyer.\",\"currentDomainStrength\":\"Strong .com|Weak .io|Weak .ai|Long domain|Unknown\",\"brandFit\":95,\"keywordMatch\":90,\"commercialFit\":92,\"likelihoodToBuy\":88,\"score\":91,\"priority\":\"Hot\"}]}";

const prevAll = $('Parse Plan').all();

const groups = {};

$input.all().forEach((item, i) => {
  const prev = prevAll[i].json;

  if (!groups[prev.domain]) {
    groups[prev.domain] = {
      domain: prev.domain,
      plan: prev.plan,
      organic: [],
      places: []
    };
  }

  const serp = item.json;

  groups[prev.domain].organic.push(...(serp.organic || []));
  groups[prev.domain].places.push(...(serp.places || []));
});

return Object.values(groups).map(g => {

  const seenP = new Set();
  const seenO = new Set();

  const places = g.places
    .filter(p => {
      const k = (p.title || '').toLowerCase();
      if (seenP.has(k)) return false;
      seenP.add(k);
      return true;
    })
    .slice(0, 25)
    .map(p => ({
      name: p.title,
      website: p.website || '',
      rating: p.rating || '',
      reviews: p.ratingCount || '',
      address: p.address || ''
    }));

  const organic = g.organic
    .filter(r => {
      if (seenO.has(r.link)) return false;
      seenO.add(r.link);
      return true;
    })
    .slice(0, 20)
    .map(r => ({
      title: r.title,
      link: r.link,
      snippet: r.snippet
    }));

  const user =
    'Domain: ' + g.domain +
    '\nClassification: ' + JSON.stringify(g.plan) +
    '\nMerged Google Results:\n' +
    JSON.stringify({
      organic,
      places
    }) +
    '\n\nIdentify EVERY genuine buyer now.';

  return {
    json: {
      domain: g.domain,
      plan: g.plan,
      payload: {
        model: 'claude-sonnet-4-5',
        max_tokens: 6000,
        system: DISCOVER_SYS,
        messages: [
          {
            role: 'user',
            content: user
          }
        ]
      }
    }
  };
});

const prevAll = $('Build Discover Payload').all();

const out = [];

$input.all().forEach((item, i) => {

  const prev = prevAll[i].json;

  const txt = (item.json.content || [])
    .filter(b => b.type === 'text')
    .map(b => b.text)
    .join('')
    .trim();

  const s = txt.indexOf('{');
  const e = txt.lastIndexOf('}');

  if (s === -1 || e === -1) {
    throw new Error('Discover agent returned no JSON for ' + prev.domain);
  }

  const data = JSON.parse(txt.slice(s, e + 1));

  (data.prospects || []).forEach(p => {

    out.push({
      json: {

        domain: prev.domain,

        type: prev.plan.type || '',

        city: prev.plan.city || '',

        niche: prev.plan.niche || '',

        prospect: {
          name: p.name || '',
          website: p.website || '',
          industry: p.industry || 'Unknown',
          why: p.why || '',

          priority: p.priority || '',

          score: Number(p.score || 0),

          brandFit: Number(p.brandFit || 0),

          keywordMatch: Number(p.keywordMatch || 0),

          commercialFit: Number(p.commercialFit || 0),

          likelihoodToBuy: Number(p.likelihoodToBuy || 0),

          currentDomainStrength: p.currentDomainStrength || 'Unknown'
        },

        serperBody: {
          q: '"' + (p.name || '') + '" ' + (p.website || '') + ' contact email owner',
          num: 8
        }

      }
    });

  });

});

return out;

const prevAll = $('Build Enrich Payload').all();

return $input.all().map((item, i) => {

  const prev = prevAll[i].json;

  let e = {
    email: '',
    contactName: '',
    signal: ''
  };

  try {
    const txt = (item.json.content || [])
      .filter(b => b.type === 'text')
      .map(b => b.text)
      .join('')
      .trim();

    const s = txt.indexOf('{');
    const x = txt.lastIndexOf('}');

    if (s !== -1 && x !== -1) {
      e = JSON.parse(txt.slice(s, x + 1));
    }
  } catch (err) {}

  return {
    json: {
      Domain: prev.domain,
      Type: prev.type,
      City: prev.city,
      Niche: prev.niche,

      Prospect: prev.prospect.name,
      Website: prev.prospect.website || '',

      Priority: prev.prospect.priority || '',
      "Overall Score": prev.prospect.score || '',
      "Brand Fit": prev.prospect.brandFit || '',
      "Keyword Match": prev.prospect.keywordMatch || '',
      "Commercial Fit": prev.prospect.commercialFit || '',
      "Buy Likelihood": prev.prospect.likelihoodToBuy || '',

      Why: prev.prospect.why || '',

      Email: e.email || '',
      Contact: e.contactName || '',
      Signal: e.signal || '',

      Status: 'New',
      Date: new Date().toISOString().slice(0, 10)
    }
  };

});
